            question:
              'Consider the functions $$f(x)=\\dfrac{1}{x-4}+1$$, for $$x \\ne 4$$, and $$g(x)=x-3$$ for $$x \\in \\mathbb{R}$$.\n The graphs of $$f$$ and $$g$$ intersect at points A and B. The coordinates of A are $$(3,0)$$.\n The shaded region is enclosed by the graph of $$f$$, the graph of $$g$$, the $$x$$-axis, and the line $$x=k$$, where $$k \\in \\mathbb{Z}$$.\n The area of the shaded region can be written as $$\\ln(p)+8$$, where $$p \\in \\mathbb{Z}$$.\n (a) Find the coordinates of B. [5]\n (b) Find the value of $$k$$ and the value of $$p$$. [10]',
