            question:
              'Consider the series $$\\ln a + p\\ln a + \\dfrac13\\ln a + \\cdots$$, where $$a\\in\\mathbb{R}$$, $$a>1$$ and $$p\\in\\mathbb{R}$$, $$p\\ne0$$.\n Consider the case where the series is geometric.\n (a)(i) Show that $$p = \\pm\\dfrac{1}{\\sqrt3}$$. [2]\n (a)(ii) Given that $$p>0$$ and $$S_\\infty = 3+\\sqrt3$$, find the value of $$a$$. [3]\n Now consider the case where the series is arithmetic with common difference $$d$$.\n (b)(i) Show that $$p=\\dfrac23$$. [3]\n (b)(ii) Write down $$d$$ in the form $$q\\ln a$$, where $$q\\in\\mathbb{Q}$$. [1]\n (b)(iii) The sum of the first $$n$$ terms of the series is $$-3\\ln a$$. Find the value of $$n$$. [6]',
