            marks: 12,
            marksBreakdown: null,
            calculator: true,
            question:
              "Helen and Jane both commence new jobs, each starting on an annual salary of $$\\$70\\,000$$. At the start of each new year, Helen receives an annual salary increase of $$\\$2400$$. Let $$\\$H_n$$ represent Helen's annual salary at the start of her $$n$$th year of employment. At the start of each new year, Jane receives an annual salary increase of 3% of her previous year's annual salary. Jane's annual salary, $$\\$J_n$$, at the start of her $$n$$th year of employment is given by $$J_n = 70\\,000(1.03)^{n-1}$$. At the start of year $$N$$, Jane's annual salary exceeds Helen's annual salary for the first time.\n (a) Show that $$H_n = 2400n + 67\\,600$$. [2]\n (b) Given that $$J_n$$ follows a geometric sequence, state the value of the common ratio, $$r$$. [1]\n (c)(i) Find the value of $$N$$. [3]\n (c)(ii) For the value of $$N$$ found in part (c)(i), state Helen's annual salary and Jane's annual salary, correct to the nearest dollar. [2]\n (d) Find Jane's total earnings at the start of her 10th year of employment. Give your answer correct to the nearest dollar. [4]",
            answer:
              '(a) AG (b) $$r=1.03$$ (c)(i) $$N=11$$ (c)(ii) $$H_{11}=\\$94\\,000,\\ J_{11}=\\$94\\,074$$ (d) $$\\$711\\,137$$',
            solution:
              '(a) Use $$u_n=u_1+(n-1)d$$ with $$u_1=70\\,000, d=2400$$: $$H_n=70\\,000+2400(n-1)=2400n+67\\,600$$ (AG).\n (b) $$r=1.03$$.\n (c)(i) Use table/GDC to find least $$N$$ with $$J_N>H_N$$: $$N=10.800...\\Rightarrow N=11$$.\n (c)(ii) $$H_{11}=94\\,000$$, $$J_{11}=94\\,074$$.\n (d) At the start of year 10, Jane has worked 9 years; use $$S_9=\\dfrac{J_1(r^9-1)}{r-1}$$ with $$J_1=70\\,000, r=1.03$$: $$S_9=711\\,137.42...\\approx \\$711\\,137$$.',
            questionType: 'Sequences and series, financial applications',
