            question:
              'An infinite geometric series has first term $$u_1 = a$$ and second term $$u_2 = \\dfrac{1}{4}a^2 - 3a$$, where $$a>0$$.\n (a) Find the common ratio in terms of $$a$$. [2]\n (b) Find the values of $$a$$ for which the sum to infinity of the series exists. [3]\n (c) Find the value of $$a$$ when $$S_{\\infty} = 76$$. [3]',
            answer: '(a) $$r=\\dfrac{1}{4}a-3$$ (b) $$8<a<16$$ (c) $$a=\\dfrac{76}{5}=15.2$$',
            solution:
              '(a) $$r=\\dfrac{u_2}{u_1}=\\dfrac{\\frac{1}{4}a^2-3a}{a}=\\dfrac{1}{4}a-3$$.\n (b) Require $$|r|<1$$: $$-1\\le \\dfrac{1}{4}a-3\\le1 \\Rightarrow 8<a<16$$.\n (c) $$\\dfrac{a}{1-\\left(\\frac{1}{4}a-3\\right)}=76 \\Rightarrow a=76\\left(4-\\dfrac{1}{4}a\\right)$$ solved gives $$a=\\dfrac{76}{5}=15.2$$.',
