            solution:
              '(a) $$1700\\left(1+\\dfrac{0.0274}{2}\\right)^{20}=2231.71$$.\n (b) $$1700\\left(1+\\dfrac{r}{100}\\right)^{10}=2231.71 \\Rightarrow r=2.75876...\\approx2.76$$.\n (c) Interest $$=2231.71-1700=531.71$$.',
            questionType: 'Financial mathematics, compound interest',
            diagram: null,
            subtopicSlug: 'financial-maths',
