            question:
              'Let $$f(x) = 1+e^{-x}$$ and $$g(x) = 2x+p$$, for $$x \\in \\mathbb{R}$$, where $$p$$ is a constant.\n (a) Find $$(g \\circ f)(x)$$. [2]\n (b) Given that $$\\displaystyle\\lim_{x\\to+\\infty}(g\\circ f)(x) = -3$$, find the value of $$p$$. [4]',
            answer: '(a) $$(g\\circ f)(x) = 2+2e^{-x}+p$$\n (b) $$p=-5$$',
