            question:
              'The function $$f$$ is defined by $$f(x) = \\dfrac{2x+4}{3-x}$$, where $$x\\in\\mathbb{R},\\ x\\neq3$$.\n (a)(i) Write down the equation of the vertical asymptote of the graph of $$f$$. [1]\n (a)(ii) Write down the equation of the horizontal asymptote of the graph of $$f$$. [1]\n (b)(i) Find the coordinates where the graph of $$f$$ crosses the x-axis. [1]\n (b)(ii) Find the coordinates where the graph of $$f$$ crosses the y-axis. [1]\n (c) Sketch the graph of $$f$$ on a set of axes. [1]',
            answer:
              '(a)(i) $$x=3$$ (a)(ii) $$y=-2$$ (b)(i) $$(-2,0)$$ (b)(ii) $$\\left(0,\\dfrac43\\right)$$',
            solution:
              '(a)(i) Vertical asymptote where the denominator is 0: $$x=3$$. (1 mark)\n (a)(ii) As $$x\\to\\pm\\infty$$, $$f(x)\\to\\dfrac{2x}{-x}=-2$$, so horizontal asymptote $$y=-2$$. (1 mark)\n (b)(i) Set numerator $$=0$$: $$2x+4=0 \\Rightarrow x=-2$$, giving $$(-2,0)$$. (1 mark)\n (b)(ii) $$f(0)=\\dfrac43$$, giving $$\\left(0,\\dfrac43\\right)$$. (1 mark)\n (c) Two-branch rational function shape in correct quadrants, asymptotic to $$x=3$$ and $$y=-2$$. (1 mark)',
