            question:
              'Consider the function $$f(x) = -2(x-1)(x+3)$$, for $$x\\in\\mathbb{R}$$.\n (a)(i) Find the x-coordinates of the x-intercepts of the graph of $$f$$. [2]\n (a)(ii) Find the coordinates of the vertex. [3]\n (b) The function $$f$$ can be written in the form $$f(x)=-2(x-h)^2+k$$. Write down the value of $$h$$ and the value of $$k$$. [2]',
