            question:
              'Consider the points A$$(-2,20)$$, B$$(4,6)$$ and C$$(-14,12)$$. The line $$L$$ passes through the point A and is perpendicular to $$[BC]$$.\n (a) Find the equation of $$L$$. [3]\n (b) The line $$L$$ passes through the point $$(p, 2)$$. Find the value of $$p$$. [2]',
            answer: '(a) $$y = 3x + 26$$\n (b) $$p = -8$$',
