            question:
              'A quadratic function $$f$$ can be written in the form $$f(x)=a(x-p)(x-3)$$. The graph of $$f$$ has axis of symmetry $$x=2.5$$ and y-intercept at $$(0,-6)$$.\n (a) Find the value of $$p$$. [3]\n (b) Find the value of $$a$$. [3]\n (c) The line $$y=kx-5$$ is a tangent to the curve of $$f$$. Find the values of $$k$$. [8]',
            answer: '(a) $$p=2$$\n (b) $$a=-1$$\n (c) $$k=3$$ or $$k=7$$',
            solution:
              '(a) Axis of symmetry is the midpoint of roots $$p$$ and $$3$$: $$\\dfrac{p+3}{2}=2.5 \\Rightarrow p=2$$. (3 marks)\n (b) Substitute $$(0,-6)$$: $$a(0-2)(0-3)=-6 \\Rightarrow 6a=-6 \\Rightarrow a=-1$$. (3 marks)\n (c) $$f(x)=-(x-2)(x-3)=-x^2+5x-6$$. Setting $$f(x)=kx-5$$: $$-x^2+5x-6=kx-5 \\Rightarrow x^2+(k-5)x+1=0$$. For tangency, discriminant $$=0$$: $$(k-5)^2-4=0 \\Rightarrow k-5=\\pm2 \\Rightarrow k=3$$ or $$k=7$$. (8 marks)',
            questionType: 'Quadratic Functions',
            diagram: null,
            subtopicSlug: 'quadratic-functions',
