              'The following diagram shows a circle with centre $$O$$ and radius $$3$$. Points A, P and B lie on the circumference of the circle. Chord $$[AB]$$ has length $$L$$ and $$A\\hat{O}B = \\theta$$ radians.\n a. Show that arc APB has length $$6\\pi - 3\\theta$$. [2]\n b. Show that $$L = \\sqrt{18-18\\cos\\theta}$$. [2]\n c. Arc APB is twice the length of chord $$[AB]$$. Find the value of $$\\theta$$. [3]',
