            question:
              'The quadratic equation $$(k-1)x^2+2x+(2k-3)=0$$, where $$k \\in \\mathbb{R}$$, has real distinct roots. Find the range of possible values for $$k$$.',
            answer: '$$\\dfrac{1}{2} < k < 2$$',
