            question:
              'Consider the lines $$L_1$$ and $$L_2$$ with respective equations $$L_1: y=-\\dfrac{2}{3}x+9$$ and $$L_2: y=\\dfrac{2}{5}x-\\dfrac{19}{5}$$. A third line, $$L_3$$, has gradient $$-\\dfrac{3}{4}$$.\n a. Find the point of intersection of $$L_1$$ and $$L_2$$. [2]\n b. Write down a direction vector for $$L_3$$. [1]\n c. $$L_3$$ passes through the intersection of $$L_1$$ and $$L_2$$. Write down a vector equation for $$L_3$$. [2]',
