            calculator: true,
            question:
              'The amount, $$N$$, of carbon-14 present in a plant $$t$$ years after its death can be modelled by $$N=N_0e^{-kt}$$ where $$t\\ge 0$$ and $$N_0,k$$ are positive constants. At death, a plant has 100 units of carbon-14. The time for half the original amount to decay is 5730 years.\n a. Show that $$N_0=100$$. [1]\n b. Show that $$k=\\dfrac{\\ln2}{5730}$$. [3]\n c. Find, correct to the nearest 10 years, the time taken after death for 25% of the carbon-14 to decay. [3]',
            answer:
              'a. $$N_0=100$$ (shown)\n b. $$k=\\dfrac{\\ln2}{5730}$$ (shown)\n c. $$t\\approx 2380$$ years',
            solution:
              'a. At $$t=0$$: $$100=N_0e^0 \\Rightarrow N_0=100$$.\n b. Half-life condition: $$50=100e^{-5730k}\\Rightarrow e^{-5730k}=\\tfrac12 \\Rightarrow -5730k=\\ln\\tfrac12=-\\ln2 \\Rightarrow k=\\dfrac{\\ln2}{5730}$$.\n c. 75% remains: $$75=100e^{-kt}$$; solve for $$t$$: $$t=2378.16\\ldots \\approx 2380$$ years (nearest 10 years).',
            questionType: 'Exponential decay, logarithms',
            diagram: null,
            subtopicSlug: 'exponential-and-logarithmic-functions',
