            calculator: true,
            question:
              'The function $$f$$ is defined by $$f(x)=\\dfrac{4x+1}{x+4}$$, where $$x\\in\\mathbb{R},\\ x\\ne-4$$. The graphs of $$f$$ and $$f^{-1}$$ intersect at $$x=p$$ and $$x=q$$, where $$p<q$$.\n a.i. Write down the equation of the vertical asymptote. [1]\n a.ii. Find the equation of the horizontal asymptote. [2]\n b.i. Find $$f^{-1}(x)$$. [4]\n b.ii. Using an algebraic approach, show that the graph of $$f^{-1}$$ is obtained by a reflection of the graph of $$f$$ in the $$y$$-axis followed by a reflection in the $$x$$-axis. [4]\n c.i. Find the value of $$p$$ and the value of $$q$$. [2]\n c.ii. Hence, find the area enclosed by the graph of $$f$$ and the graph of $$f^{-1}$$. [3]',
            answer:
              'a.i. $$x=-4$$\n a.ii. $$y=4$$\n b.i. $$f^{-1}(x)=\\dfrac{1-4x}{x-4}$$\n b.ii. Shown\n c.i. $$p=-1,\\ q=1$$\n c.ii. Area $$=0.675$$',
            solution:
              'a.i. Vertical asymptote where denominator $$=0$$: $$x=-4$$.\n a.ii. As $$x\\to\\infty,\\ f(x)\\to4$$, so $$y=4$$.\n b.i. Interchange $$x$$ and $$y$$ in $$y=\\dfrac{4x+1}{x+4}$$ and solve for $$y$$: $$f^{-1}(x)=\\dfrac{1-4x}{x-4}$$.\n b.ii. $$f(-x)=\\dfrac{-4x+1}{-x+4}$$; then $$-f(-x)=\\dfrac{4x-1}{-x+4}=\\dfrac{1-4x}{x-4}=f^{-1}(x)$$, confirming the double reflection.\n c.i. Solve $$f(x)=f^{-1}(x)$$ graphically/algebraically: $$p=-1,\\ q=1$$.\n c.ii. $$\\displaystyle\\int_{-1}^{1}\\left(\\dfrac{4x+1}{x+4}-\\dfrac{1-4x}{x-4}\\right)dx=0.675231\\ldots\\approx0.675$$.',
