            question:
              'The base of an electric iron can be modelled as a pentagon ABCDE, where: BCDE is a rectangle with sides of length $$(x+3)$$ cm and $$(x+5)$$ cm; ABE is an isosceles triangle, with AB $$=$$ AE and a height of $$x$$ cm; the area of ABCDE is $$222\\text{ cm}^2$$. Insulation tape is wrapped around the perimeter of the base of the iron, ABCDE. F is the point on AB such that BF $$=8$$ cm. A heating element in the iron runs in a straight line, from C to F.\n (a)(i) Write down an equation for the area of ABCDE using the above information.\n (a)(ii) Show that the equation in part (a)(i) simplifies to $$3x^2+19x-414=0$$.\n (b) Find the length of CD.\n (c) Show that angle $$B\\hat{A}E=67.4^\\circ$$, correct to one decimal place.\n (d) Find the length of the perimeter of ABCDE.\n (e) Calculate the length of CF.',
