            subtopic: 'Trigonometric functions and modelling',
            subtopicDetail: 'Trigonometric modelling and rate of change (differentiation)',
            difficulty: 'Hard',
            marks: 15,
            marksBreakdown: null,
            calculator: true,
            question:
              'The following diagram shows a water wheel with centre O and radius 10 metres. Water flows into buckets, turning the wheel clockwise at a constant speed. The height, $$h$$ metres, of the top of a bucket above the ground $$t$$ seconds after it passes through point A is modelled by $$h(t)=13+8\\cos\\left(\\dfrac{\\pi}{18}t\\right)-6\\sin\\left(\\dfrac{\\pi}{18}t\\right)$$, for $$t\\ge0$$. A bucket moves around to point B which is at a height of $$4.06$$ metres above the ground. It takes $$k$$ seconds for the top of this bucket to go from point A to point B. The chord $$[AB]$$ is $$17.0$$ metres, correct to three significant figures.\n (a)(i) Find the height of point A above the ground.\n (a)(ii) Calculate the number of seconds it takes for the water wheel to complete one rotation.\n (a)(iii) Hence find the number of rotations the water wheel makes in one hour.\n (b) Find $$k$$.\n (c) Find $$A\\hat{O}B$$.\n (d) Determine the rate of change of $$h$$ when the top of the bucket is at B.',
            answer:
              '(a)(i) $$21$$ m (a)(ii) $$36$$ s (a)(iii) $$100$$ rotations (b) $$k=11.7$$ (c) $$A\\hat OB=2.03$$ rad ($$116^\\circ$$) (d) rate $$=-0.782\\text{ m s}^{-1}$$',
            solution:
              "(a)(i) $$h(0)=13+8(1)-6(0)=21$$ m.\n (a)(ii) Period $$=\\dfrac{2\\pi}{\\pi/18}=36$$ s.\n (a)(iii) $$\\dfrac{3600}{36}=100$$ rotations.\n (b) Solve $$4.06=13+8\\cos(\\frac{\\pi}{18}k)-6\\sin(\\frac{\\pi}{18}k)\\Rightarrow k=11.7$$.\n (c) Cosine rule with $$OA=OB=10$$, $$AB=17.0$$: $$\\cos(A\\hat OB)=\\dfrac{10^2+10^2-17.0^2}{2(10)(10)}\\Rightarrow A\\hat OB=2.03$$ rad.\n (d) $$h'(11.6510)=-0.782\\text{ m s}^{-1}$$ (using GDC differentiation).",
