              'OAB is a sector of the circle with centre O and radius $$r$$, as shown in the following diagram. The angle AOB is $$\\theta$$ radians, where $$0<\\theta<\\dfrac{\\pi}{2}$$. The point C lies on OA and OA is perpendicular to BC.\n (a) Show that $$OC=r\\cos\\theta$$.\n (b) Find the area of triangle OBC in terms of $$r$$ and $$\\theta$$.\n (c) Given that the area of triangle OBC is $$\\dfrac{3}{5}$$ of the area of sector OAB, find $$\\theta$$.',
