            question:
              'Note: in this question, distance is in millimetres. Let $$f(x)=x+a\\sin\\left(x-\\dfrac{\\pi}{2}\\right)+a$$, for $$x\\ge0$$. The graph of $$f$$ passes through the origin. Let $$P_k$$ be any point on the graph of $$f$$ with $$x$$-coordinate $$2k\\pi$$, where $$k\\in\\mathbb{N}$$. A straight line $$L$$ passes through all the points $$P_k$$. Diagram 1 shows a saw; the length of the toothed edge is the distance AB. The toothed edge of the saw can be modelled using the graph of $$f$$ and the line $$L$$ (Diagram 2). The shaded part on the graph is called a tooth: the region enclosed by the graph of $$f$$ and the line $$L$$, between $$P_k$$ and $$P_{k+1}$$.\n (a) Show that $$f(2\\pi)=2\\pi$$.\n (b)(i) Find the coordinates of $$P_0$$ and of $$P_1$$.\n (b)(ii) Find the equation of $$L$$.\n (c) Show that the distance between the $$x$$-coordinates of $$P_k$$ and $$P_{k+1}$$ is $$2\\pi$$.\n (d) A saw has a toothed edge which is 300 mm long. Find the number of complete teeth on this saw.',
            answer:
              '(a) $$f(2\\pi)=2\\pi$$ (AG) (b)(i) $$P_0(0,0),\\ P_1(2\\pi,2\\pi)$$ (b)(ii) $$L: y=x$$ (c) distance $$=2\\pi$$ (AG) (d) 33 teeth',
            solution:
              '(a) $$f(2\\pi)=2\\pi+a\\sin\\left(\\dfrac{3\\pi}{2}\\right)+a=2\\pi-a+a=2\\pi$$ (AG).\n (b)(i) Substituting $$k=0,1$$: $$P_0(0,0)$$, $$P_1(2\\pi,2\\pi)$$.\n (b)(ii) Gradient $$=\\dfrac{2\\pi-0}{2\\pi-0}=1\\Rightarrow y=x$$.\n (c) $$x$$-coordinates differ by $$2(k+1)\\pi-2k\\pi=2\\pi$$ (AG).\n (d) Hypotenuse of one tooth (vertical/horizontal both $$2\\pi$$): $$x=\\dfrac{300}{\\sqrt2}=212.132$$; number of teeth $$=\\dfrac{212.132}{2\\pi}=33.76\\Rightarrow33$$ complete teeth.',
