              'The following diagram shows quadrilateral ABCD. $$AB=11$$ cm, $$BC=6$$ cm, $$B\\hat{A}D=100^\\circ$$, and $$C\\hat{B}D=82^\\circ$$.\n (a) Find DB.\n (b) Find DC.',
