            question:
              'Two points P and Q have coordinates $$(3,2,5)$$ and $$(7,4,9)$$ respectively. Let $$\\overrightarrow{PR}=6\\mathbf{i}-\\mathbf{j}+3\\mathbf{k}$$.\n (a)(i) Find $$\\overrightarrow{PQ}$$.\n (a)(ii) Find $$|\\overrightarrow{PQ}|$$.\n (b) Find the angle between $$\\overrightarrow{PQ}$$ and $$\\overrightarrow{PR}$$.\n (c) Find the area of triangle PQR.\n (d) Hence or otherwise find the shortest distance from R to the line through P and Q.',
