            marksBreakdown: null,
            calculator: true,
            question:
              'At Grande Anse Beach the height of the water in metres is modelled by the function $$h(t)=p\\cos(q\\times t)+r$$, where $$t$$ is the number of hours after 21:00 hours on 10 December 2017, for $$0\\le t\\le72$$. The point $$A(6.25,0.6)$$ represents the first low tide and $$B(12.5,1.5)$$ represents the next high tide.\n (a)(i) How much time is there between the first low tide and the next high tide?\n (a)(ii) Find the difference in height between low tide and high tide.\n (b)(i) Find the value of $$p$$.\n (b)(ii) Find the value of $$q$$.\n (b)(iii) Find the value of $$r$$.\n (c) There are two high tides on 12 December 2017. At what time does the second high tide occur?',
            answer:
              '(a)(i) $$6.25$$ hours (a)(ii) $$0.9$$ m (b)(i) $$p=0.45$$ (b)(ii) $$q=\\dfrac{4\\pi}{25}\\approx0.503$$ (b)(iii) $$r=1.05$$ (c) 23:00',
            solution:
              '(a)(i) $$12.5-6.25=6.25$$ hours.\n (a)(ii) $$1.5-0.6=0.9$$ m.\n (b)(i) $$p=\\dfrac{\\max-\\min}{2}=\\dfrac{0.9}{2}=0.45$$.\n (b)(ii) Period $$=12.5\\Rightarrow q=\\dfrac{2\\pi}{12.5}=\\dfrac{4\\pi}{25}\\approx0.503$$.\n (b)(iii) $$r=\\dfrac{\\max+\\min}{2}=0.6+0.45=1.05$$.\n (c) High tides recur every 12.5 h after $$t=12.5$$; second high tide on 12 Dec occurs at $$t=50\\Rightarrow$$ 23:00.',
