            question:
              'The following diagram shows the graph of $$f(x)=a\\sin bx+c$$, for $$0\\le x\\le12$$. The graph of $$f$$ has a minimum point at $$(3,5)$$ and a maximum point at $$(9,17)$$. The graph of $$g$$ is obtained from the graph of $$f$$ by a translation of $$\\begin{pmatrix}k\\\\0\\end{pmatrix}$$. The maximum point on the graph of $$g$$ has coordinates $$(11.5,17)$$. The graph of $$g$$ changes from concave-up to concave-down when $$x=w$$.\n (a)(i) Find the value of $$c$$.\n (a)(ii) Show that $$b=\\dfrac{\\pi}{6}$$.\n (a)(iii) Find the value of $$a$$.\n (b)(i) Write down the value of $$k$$.\n (b)(ii) Find $$g(x)$$.\n (c)(i) Find $$w$$.\n (c)(ii) Hence or otherwise, find the maximum positive rate of change of $$g$$.',
