            calculator: true,
            question:
              'A restaurant serves desserts in glasses shaped as a cone and a hemisphere. The diameter of a cone glass is 7.2 cm and its height is 11.8 cm. The volume of a hemisphere glass is $$225\\text{ cm}^3$$. The regular dessert (hemisphere, filled with chocolate mousse) costs the restaurant $1.89 per glass. The special dessert (cone, filled to half its height with orange paste, then chocolate mousse) uses orange paste costing $7.42 per $$100\\text{ cm}^3$$. A chef prepares 50 desserts: $$x$$ regular and $$y$$ special. The total ingredient cost for the 50 desserts is $111.44.\n (a) Show that the volume of a cone shaped glass is $$160\\text{ cm}^3$$, correct to 3 significant figures.\n (b) Calculate the radius, $$r$$, of a hemisphere shaped glass.\n (c) Find the cost of $$100\\text{ cm}^3$$ of chocolate mousse.\n (d) Show that there is $$20\\text{ cm}^3$$ of orange paste in each special dessert.\n (e) Find the total cost of the ingredients of one special dessert.\n (f) Find the value of $$x$$.',
