              'All lengths in this question are in centimetres. A solid metal ornament is in the shape of a right pyramid, with vertex V and square base ABCD. The centre of the base is X. Point V has coordinates $$(1,5,0)$$ and point A has coordinates $$(-1,1,6)$$. The volume of the pyramid is $$57.2\\text{ cm}^3$$, correct to three significant figures.\n (a) Find AV.\n (b) Given that $$A\\hat{V}B=40^\\circ$$, find AB.\n (c) Find the height of the pyramid, VX.\n (d) A second ornament is a cuboid with a rectangular base of length $$2x$$ cm, width $$x$$ cm and height $$y$$ cm, with the same volume as the pyramid. The cuboid has a minimum surface area of $$S\\text{ cm}^2$$. Find the value of $$S$$.',
