            question:
              'A scientist conducted a nine-week experiment on two plants, $$A$$ and $$B$$, of the same species, to determine the effect of a new fertilizer (given to Plant A only). The height of Plant A, $$h_A$$ cm, at time $$t$$ weeks is modelled by $$h_A(t)=\\sin(2t+6)+9t+27$$, $$0\\le t\\le9$$. The height of Plant B, $$h_B$$ cm, is modelled by $$h_B(t)=8t+32$$, $$0\\le t\\le9$$.\n (a)(i) Find the initial height of Plant B.\n (a)(ii) Find the initial height of Plant A, correct to three significant figures.\n (b) Find the values of $$t$$ when $$h_A(t)=h_B(t)$$.\n (c) For $$0\\le t\\le9$$, find the total amount of time when the rate of growth of Plant B was greater than the rate of growth of Plant A.',
            answer:
              '(a)(i) $$32$$ cm (a)(ii) $$26.7$$ cm (b) $$t=4.01,\\ 4.70,\\ 5.88$$ (weeks) (c) total time $$=3.14$$ weeks ($$=\\pi$$)',
            solution:
              "(a)(i) $$h_B(0)=32$$ cm.\n (a)(ii) $$h_A(0)=\\sin(6)+27=26.7205\\approx26.7$$ cm.\n (b) Solve $$\\sin(2t+6)+9t+27=8t+32\\Rightarrow t=4.00746,\\ 4.70343,\\ 5.88332\\Rightarrow t=4.01,\\ 4.70,\\ 5.88$$ (GDC).\n (c) Solve $$h_A'(t)=h_B'(t)\\Rightarrow2\\cos(2t+6)+9=8$$; roots give intervals $$1.18879<t<2.23598$$, $$4.33038<t<5.37758$$, $$7.47197<t<8.51917$$ (each of width $$\\frac{\\pi}{3}$$); total time $$=3\\left(\\frac{\\pi}{3}\\right)=\\pi\\approx3.14$$ weeks.",
            questionType: 'Trigonometric/linear function comparison, derivatives, equation solving',
            diagram: null,
            subtopicSlug: 'trigonometric-functions-and-modelling',
