            code: '17M.2.SL.TZ1.T_5',
            session: 'May 2017',
            subtopic: 'Descriptive statistics',
            subtopicDetail: 'Descriptive statistics; normal distribution; conditional probability',
            difficulty: 'Hard',
            marks: 15,
            marksBreakdown: null,
            calculator: true,
            question:
              'The table below shows the distribution of test grades for 50 IB students at Greendale School. A student, then a second student, is chosen at random from these 50 students. The number of minutes the 50 students spent preparing for the test was normally distributed with mean 105 minutes and standard deviation 20 minutes.\n a.(i) Calculate the mean test grade of the students. [2]\n a.(ii) Calculate the standard deviation. [1]\n b. Find the median test grade. [1]\n c. Find the interquartile range. [2]\n d. Find the probability that a student chosen at random scored a grade 5 or higher. [2]\n e. Given that the first student chosen scored a grade 5 or higher, find the probability that both students scored a grade 6. [3]\n f.(i) Calculate the probability that a student spent at least 90 minutes preparing. [2]\n f.(ii) Calculate the expected number of students who spent at least 90 minutes preparing. [2]',
            answer:
              'a.(i) $$4.6$$ a.(ii) $$1.46$$ b. $$5$$ c. $$2$$ d. $$0.52$$ e. $$\\tfrac{45}{637}\\approx0.0706$$ f.(i) $$0.773$$ f.(ii) $$38.7$$',
            solution:
              'a. Mean $$=\\dfrac{1(1)+3(2)+7(3)+13(4)+11(5)+10(6)+5(7)}{50}=\\dfrac{230}{50}=4.6$$; standard deviation $$=1.46$$ (GDC).\n b. Median grade $$=5$$.\n c. IQR $$=6-4=2$$.\n d. $$P(\\text{grade}\\ge5)=\\dfrac{11+10+5}{50}=\\dfrac{26}{50}=0.52$$.\n e. $$\\dfrac{10}{26}\\times\\dfrac{9}{49}=\\dfrac{45}{637}\\approx0.0706$$.\n f. $$P(X\\ge90)=0.773$$ (normal distribution, GDC); expected number $$=0.773\\times50\\approx38.7$$.',
            questionType: 'Descriptive statistics, normal distribution, conditional probability',
            diagram:
              'https://drive.google.com/file/d/1jFUTM3C_iYveYHHTtDei8TnzUoIpgwOl/view?usp=sharing',
            subtopicSlug: 'descriptive-statistics',
