            session: 'May 2019',
            subtopic: 'Descriptive statistics',
            subtopicDetail: 'Descriptive statistics; chi-squared test for independence',
            difficulty: 'Hard',
            marks: 15,
            marksBreakdown: null,
            calculator: true,
            question:
              "A survey asked people how many pets they own (summary table given in source) and, separately, each member's age category and preferred pet (contingency table given in source). A $$\\chi^2$$ test is carried out at the $$10\\%$$ significance level.\n a. Write down the total number of people who are pet owners. [1]\n b. Write down the modal number of pets. [1]\n c.(i) Write down the median number of pets. (ii) the lower quartile. (iii) the upper quartile. [3]\n d. Write down the ratio of teenagers to non-teenagers in simplest form. [1]\n e.(i) State the null hypothesis. (ii) State the alternative hypothesis. [2]\n f. Write down the number of degrees of freedom. [1]\n g. Calculate the expected number of teenagers that prefer cats. [2]\n h. Use your GDC to find the $$p$$-value for this test. [2]\n i. State the conclusion for this test, giving a reason. [2]",
            answer:
              'a. $$140$$ b. $$1$$ c. median $$2$$, LQ $$1$$, UQ $$3$$ d. $$17:15$$ f. $$3$$ g. $$29.2$$ h. $$0.208$$ i. Accept $$H_0$$ (fail to reject), since $$0.208>0.1$$',
            solution:
              'a. Total pet owners $$=140$$.\n b. Mode $$=1$$; median $$=2$$; lower quartile $$=1$$; upper quartile $$=3$$.\n d. Ratio teenagers:non-teenagers $$=17:15$$.\n e. $$H_0$$: preferred pet is independent of age category; $$H_1$$: preferred pet is not independent of age.\n f. Degrees of freedom $$=3$$.\n g. Expected $$=\\dfrac{85\\times55}{160}=29.2$$.\n h. $$p=0.208$$.\n i. Since $$0.208>0.1$$, accept $$H_0$$ (fail to reject the null hypothesis).',
            questionType: 'Descriptive statistics, Chi-squared test for independence',
            diagram:
              'https://drive.google.com/file/d/1O5-ZrtRRbY0GKp-tNUtQpxc9J9Xc_lc5/view?usp=sharing\n\nhttps://drive.google.com/file/d/1o0naCUuY7hjJkQqVw0W8-WyyznHyswlv/view?usp=sharing',
            subtopicSlug: 'descriptive-statistics',
