            marks: 14,
            marksBreakdown: null,
            calculator: true,
            question:
              "The weight, $$W$$, of basketball players in a tournament is normally distributed, mean 65 kg, standard deviation 5 kg. The probability a player's weight is within 1.5 standard deviations of the mean is $$q$$. A coach observed 60 players to test whether performance and weight are independent (contingency table given in source), using a $$\\chi^2$$ test at the $$5\\%$$ level.\n a.(i) Find the probability a player weighs less than 61 kg. [2]\n a.(ii) In a training session of 40 players, find the expected number weighing less than 61 kg. [2]\n b.(i) Sketch a normal curve to represent $$q$$. [2]\n b.(ii) Find the value of $$q$$. [1]\n c. Given $$P(W>k)=0.225$$, find the value of $$k$$. [2]\n d.(i) State the null hypothesis. [1]\n d.(ii) Find the $$p$$-value. [2]\n e. State a conclusion for this test, justifying your answer. [2]",
