            marks: 10,
            marksBreakdown: null,
            calculator: true,
            question:
              'Ten students were surveyed about hours, $$x$$, spent browsing the Internet during week 1. $$\\sum_{i=1}^{10}x_i=252$$, $$\\sigma=5$$, median $$=27$$.\n a. Find the mean number of hours spent browsing the Internet. [2]\n b. During week 2, each student spent an additional 5 hours browsing. For week 2, write down (i) the mean; (ii) the standard deviation. [2]\n c. During week 3, each student spent $$5\\%$$ less time than in week 1. For week 3, find (i) the median; (ii) the variance. [6]',
            answer:
              'a. $$25.2$$ hours b.(i) $$30.2$$ hours (ii) $$\\sigma=5$$ hours c.(i) $$25.7$$ hours (ii) $$22.6$$',
            solution:
              'a. Mean $$=\\dfrac{252}{10}=25.2$$ hours.\n b. Adding a constant (5) to all data: new mean $$=25.2+5=30.2$$; standard deviation unchanged, $$\\sigma=5$$.\n c. Scaling by $$0.95$$: new median $$=0.95\\times27=25.65\\approx25.7$$ hours; new standard deviation $$=0.95\\times5=4.75$$, so new variance $$=4.75^2=22.5625\\approx22.6$$.',
            questionType:
              'Descriptive statistics (effect of linear transformations on mean, median, variance)',
            diagram: null,
