            question:
              'All answers in this question should be given to 4 sf. In a weekly lottery, tickets cost \\$2. In the first week, a player receives \\$D per ticket with a given probability distribution (table in source, $$P(D=10)=0.03$$). The grand prize is \\$1000 in week 1; if unwon, it doubles each subsequent week.\n a. Find the value of $$c$$ (missing probability). [2]\n b. Determine whether the lottery is a fair game in the first week. Justify your answer. [4]\n c. Write an expression, in terms of $$n$$, for the value of the grand prize in the $$n$$th week (if unwon and continuing to double). [2]\n d. The $$w$$th week is the first week in which the player is expected to make a profit. Ryan buys a ticket in the $$w$$th week; his expected profit is \\$p. Find the value of $$p$$. [7]',
            answer:
              'a. $$c=0.1179$$ b. Not a fair game ($$E(D)=0.7358\\ne 2$$) c. $$1000\\times2^{n-1}$$ d. $$w=5$$, $$p=0.2358$$',
