              'A discrete random variable $$X$$ has the following probability distribution (table given in source, involving a parameter $$k$$).\n a. Show that $$2k^2-k+0.12=0$$. [1]\n b. Find the value of $$k$$, giving a reason for your answer. [3]\n c. Hence, find $$E(X)$$. [2]',
            answer: 'b. $$k=0.3$$ ($$k=0.2$$ rejected) c. $$E(X)=1.27$$',
