            question:
              "On a school excursion, students visited an amusement park's rollercoasters ($$R$$), water slides ($$W$$), and virtual reality rides ($$V$$), among 100 students. Results are shown on a Venn diagram (given in source, with regions 32, 12, 10, 9, 5 and unknowns $$a$$, $$b$$). A total of 74 students visited the rollercoasters or the water slides.\n a.(i) Find the value of $$a$$. [2]\n a.(ii) Find the value of $$b$$. [2]\n b. Find the number of students who visited at least two types of main attraction. [2]\n c. Write down the value of $$n(R\\cap W)$$. [1]\n d.(i) Find the probability that a randomly selected student visited the rollercoasters. [2]\n d.(ii) Find the probability that a randomly selected student visited the virtual reality rides. [1]\n e. Hence determine whether the events in (d)(i) and (d)(ii) are independent. Justify your reasoning. [2]",
