            difficulty: 'Hard',
            marks: 17,
            marksBreakdown: null,
            calculator: true,
            question:
              'There are three fair six-sided dice, each with two green, two yellow, and two red faces. All three are rolled. Ted plays a game: rolling all three dice is a "turn"; he wins \\$10 per green face rolled, added to his winnings; if two or more red faces are rolled in a turn, all winnings are lost and the game ends. After a turn Ted can end the game (keeping winnings) or have another turn. $$D$$ (\\$) is the amount added to his winnings after a turn; a table shows the distribution of $$D$$ in terms of $$w$$ (his winnings so far).\n a.(i) Find the probability of rolling exactly one red face. [3]\n a.(ii) Find the probability of rolling at least two red faces. [3]\n b. Show that, after a turn, the probability that Ted adds exactly \\$10 to his winnings is $$\\tfrac13$$. [5]\n c.(i) Write down the value of $$x$$ (i.e. $$P(D=20)$$). [1]\n c.(ii) Hence, find the value of $$y$$ (i.e. $$P(D=0)$$, the probability of losing all winnings). [2]\n d. Ted will always have another turn if he expects an increase to his winnings. Find the least value of $$w$$ for which Ted should end the game instead of having another turn. [3]',
            answer:
              'a.(i) $$0.444$$ (ii) $$0.259$$ b. Shown ($$\\tfrac13$$) c.(i) $$x=\\tfrac{7}{27}\\approx0.259$$ (ii) $$y=\\tfrac{4}{27}\\approx0.148$$ d. $$w=40$$',
            solution:
              'a. $$P(1\\text{ red})=3\\left(\\tfrac13\\right)\\left(\\tfrac23\\right)^2=\\tfrac49\\approx0.444$$; $$P(\\ge2\\text{ red})=1-P(0\\text{ red})-P(1\\text{ red})=\\tfrac{7}{27}\\approx0.259$$.\n b. Adding exactly \\$10 means exactly one green face and at most one red face; summing the relevant cases gives probability $$\\tfrac13$$ (AG).\n c. $$x=P(\\text{lose everything})=\\tfrac{7}{27}\\approx0.259$$ (from part (a)(ii)); using $$\\sum P=1$$: $$y=1-\\tfrac13-\\tfrac29-\\tfrac{1}{27}-\\tfrac{7}{27}=\\tfrac{4}{27}\\approx0.148$$.\n d. Expected profit for another turn: $$-w\\cdot\\tfrac{7}{27}+10\\cdot\\tfrac{9}{27}+20\\cdot\\tfrac{6}{27}+30\\cdot\\tfrac{1}{27}$$; setting $$\\ge0$$ gives critical $$w=\\tfrac{240}{7}=34.29$$, so least integer/whole-dollar value for ending is $$w=\\$40$$ (smallest value above the threshold in context).',
