            calculator: true,
            question:
              "Emlyn plays basketball; minutes played per game follow $$N(m,4^2)$$. There is a $$30\\%$$ chance he plays less than 13.6 minutes, and a $$70\\%$$ chance he plays less than 17.8 minutes. There is a $$60\\%$$ chance he plays less than $$x$$ minutes. Emlyn plays two games today. Emlyn and teammate Johan's shooting practice results (a table) are also given; on Monday, each will shoot 200 times from point $$X$$.\n a. Sketch a diagram to represent this information. [2]\n b. Show that $$m=15.7$$. [2]\n c.(i) Find the probability that Emlyn plays between 13 and 18 minutes in a game. [2]\n c.(ii) Find the probability that Emlyn plays more than 20 minutes in a game. [2]\n d. Find the value of $$x$$. [2]\n e. Find the probability he plays between 13 and 18 minutes in one game and more than 20 minutes in the other. [3]\n f. Find the expected number of successful shots Emlyn will make on Monday, based on the results from Saturday and Sunday. [2]\n g. Emlyn claims his expected number of successful shots will be more than Johan's. Determine if Emlyn's claim is correct, with justification. [2]",
