            calculator: true,
            question:
              'On one day 180 flights arrived at a particular airport. The distance travelled and arrival status (on time, slightly delayed, heavily delayed) was recorded (contingency table given in source). A $$\\chi^2$$ test is carried out at the $$10\\%$$ significance level to test whether arrival status is independent of distance travelled; the critical value is 7.779. A flight is chosen at random from the 180 recorded flights.\n a. State the alternative hypothesis. [1]\n b. Calculate the expected frequency of flights travelling at most 500 km and arriving slightly delayed. [2]\n c. Write down the number of degrees of freedom. [1]\n d.(i) Write down the $$\\chi^2$$ statistic. [2]\n d.(ii) Write down the associated $$p$$-value. [1]\n e. State, with a reason, whether you would reject the null hypothesis. [2]\n f. Write down the probability that this flight arrived on time. [2]\n g. Given that this flight was not heavily delayed, find the probability that it travelled between 500 km and 5000 km. [2]\n h. Two flights are chosen at random from those which were slightly delayed. Find the probability that each of these flights travelled at least 5000 km. [3]',
