            difficulty: 'Medium',
            marks: 14,
            marksBreakdown: '1+2+2+4+3+2',
            calculator: true,
            question:
              'A small cuboid box has a rectangular base of length $$3x$$ cm and width $$x$$ cm, where $$x>0$$. The height is $$y$$ cm, where $$y>0$$. The sum of the length, width and height is 12 cm. The volume of the box is $$V\\,\\text{cm}^3$$.\n (a) Write down an expression for $$y$$ in terms of $$x$$. [1]\n (b) Find an expression for $$V$$ in terms of $$x$$. [2]\n (c) Find $$\\dfrac{dV}{dx}$$. [2]\n (d)(i) Find the value of $$x$$ for which $$V$$ is a maximum. [4]\n (d)(ii) Justify your answer. [3]\n (e) Find the maximum volume. [2]',
            answer:
              '(a) $$y=12-4x$$\n (b) $$V=36x^2-12x^3$$\n (c) $$\\dfrac{dV}{dx}=72x-36x^2$$\n (d)(i) $$x=2$$\n (e) $$V=48\\ \\text{cm}^3$$',
            solution:
              "(a) Length $$+$$ width $$+$$ height $$=12 \\Rightarrow 3x+x+y=12\\Rightarrow y=12-4x$$.\n (b) $$V=3x\\cdot x\\cdot y=3x^2(12-4x)=36x^2-12x^3$$.\n (c) Differentiate: $$V'=72x-36x^2$$.\n (d)(i) Set $$V'=0\\Rightarrow 36x(2-x)=0\\Rightarrow x=2$$ (rejecting $$x=0$$).\n (d)(ii) $$V''=72-72x$$; $$V''(2)=-72<0$$, so maximum.\n (e) $$V=36(4)-12(8)=48$$.",
            questionType: 'Optimisation, differentiation, volume',
