            question:
              "A particle's displacement, in cm, from origin $$O$$, at time $$t$$ seconds, is $$s(t) = t\\cos t + t\\sin t, \\ 0 \\le t \\le 5$$.\n (a) Find the maximum distance of the particle from $$O$$. [3]\n (b) Find the acceleration of the particle at the instant it first changes direction. [4]",
