            marksBreakdown: null,
            calculator: true,
            question:
              'A particle P starts from point A and moves along a horizontal line. Its velocity $$v$$ cm s$$^{-1}$$ after $$t$$ seconds is $$v(t)=\\begin{cases}-2t+2, & 0\\le t\\le1\\\\ 3\\sqrt{t}+\\dfrac{4}{t^2}-7, & 1\\le t\\le12\\end{cases}$$. P is at rest when $$t=1$$ and $$t=p$$. When $$t=q$$, the acceleration of P is zero.\n (a) Find the initial velocity of $$P$$. [2]\n (b) Find the value of $$p$$. [2]\n (c)(i) Find the value of $$q$$. (ii) Hence, find the speed of P when $$t=q$$. [4]\n (d)(i) Find the total distance travelled by P between $$t=1$$ and $$t=p$$. (ii) Hence or otherwise, find the displacement of P from A when $$t=p$$. [6]',
            answer:
              '(a) $$v(0)=2$$ cm s$$^{-1}$$\n (b) $$p=5.22$$ s\n (c)(i) $$q=1.95$$ (ii) speed $$=1.76$$ cm s$$^{-1}$$\n (d)(i) distance $$=4.45$$ cm (ii) displacement $$=-3.45$$ cm',
            solution:
              "(a) $$v(0)=-2(0)+2=2$$ (M1A1)\n (b) Solve $$v=0$$ on second piece: $$p=5.22$$ (M1A1)\n (c) $$v'=0 \\Rightarrow q=1.95$$ (M1A1); speed $$=|v(1.95)|=1.76$$ (M1A1)\n (d)(i) $$\\int_1^{p}|v|\\,dt=4.45$$ (A1A1)\n (ii) displacement $$=\\int_0^1v\\,dt+\\int_1^{p}v\\,dt=1-4.45=-3.45$$ (A1M1A1)",
            questionType: 'Kinematics / Piecewise functions',
            diagram:
              'https://drive.google.com/file/d/11TslOPRlpzSBT8FAPitKibUjXylxaSWB/view?usp=sharing',
            subtopicSlug: 'kinematics',
