              'A particle P moves along a straight line. The velocity $$v$$ m s$$^{-1}$$ of P after $$t$$ seconds is given by $$v(t)=\\cos t - 5t^{\\cos t}$$, for $$0\\le t\\le \\pi$$.\n (a) Find the initial velocity of P. [2]\n (b) Find the maximum speed of P. [3]\n (c) Write down the number of times that the acceleration of P is $$0$$ m s$$^{-2}$$. [3]\n (d) Find the acceleration of P when it changes direction. [4]\n (e) Find the total distance travelled by P. [3]',
