            subtopicDetail: 'Applied integration — container/rate of change',
            difficulty: 'Hard',
            marks: 14,
            marksBreakdown: null,
            calculator: true,
            question:
              "All lengths in this question are in metres. Consider $$f(x)=\\sqrt{\\dfrac{4-x^2}{8}}$$, for $$-2\\le x\\le2$$. The shaded region enclosed by the graph of $$f$$ and the $$x$$-axis is rotated $$360°$$ about the $$x$$-axis to model a container. The volume of water in the container is given by $$g(t)$$, for $$0\\le t\\le4$$ ($$t$$ in hours, $$g(t)$$ in m$$^3$$), with rate of change $$g'(t)=0.9-2.5\\cos(0.4t^2)$$. The volume of water is increasing only when $$p<t<q$$.\n (a) Find the volume of the container. [3]\n (b)(i) Find the value of $$p$$ and of $$q$$. [3]\n (b)(ii) During the interval $$p<t<q$$, the volume of water increases by $$k$$ m$$^3$$. Find the value of $$k$$. [3]\n (c) When $$t=0$$, the volume of water in the container is $$2.3$$ m$$^3$$. The container is never completely full during the 4-hour period. Find the minimum volume of empty space in the container during the 4-hour period. [5]",
            answer:
              '(a) Volume $$\\approx4.19$$ m$$^3$$\n (b)(i) $$p=1.93,\\ q=3.56$$\n (b)(ii) $$k\\approx3.75$$\n (c) $$\\approx0.331$$ m$$^3$$',
            solution:
              "(a) $$V=\\pi\\int_{-2}^{2}\\dfrac{4-x^2}{8}dx=\\dfrac{4}{3}\\pi\\approx4.19$$ (M1A2)\n (b) $$g'(t)>0$$ on $$1.93<t<3.56$$ (M1A1A1)\n (b)(ii) $$k=\\int_{p}^{q}g'(t)\\,dt\\approx3.75$$ (M1A2)\n (c) Max water volume $$=2.3+\\int_0^{q}g'(t)\\,dt\\approx3.85$$; empty space $$=4.19-3.85\\approx0.331$$ (M1M1A1A2)",
            questionType: 'Applied integration / Rates of change',
            diagram:
              'https://drive.google.com/file/d/1cy7P_Vkc7D5iJQrezPa0Ea29tdvS9VBm/view?usp=sharing',
            subtopicSlug: 'integration',
