            question:
              'Consider the function $$f(x)=\\dfrac{1}{3}x^3+\\dfrac{3}{4}x^2-x-1$$. The function has one local maximum at $$x=p$$ and one local minimum at $$x=q$$.\n (b) Write down the $$y$$-intercept of the graph of $$y=f(x)$$. [1]\n (c) Sketch the graph of $$y=f(x)$$ for $$-3\\le x\\le3$$ and $$-4\\le y\\le15$$. [4]\n (h) Determine the range of $$f(x)$$ for $$p\\le x\\le q$$. [3]',
