            marks: 10,
            marksBreakdown: null,
            calculator: true,
            question:
              "A function $$f$$ is given by $$f(x)=(2x+2)(5-x^2)$$. The graph of $$g(x)=5^x+6x-6$$ intersects the graph of $$f$$.\n (b)(i) Expand the expression for $$f(x)$$. [1]\n (b)(ii) Find $$f'(x)$$. [3]\n (d) Draw the graph of $$f$$ for $$-3\\le x\\le3$$ and $$-40\\le y\\le20$$. Use a scale of 2 cm per unit on the $$x$$-axis and 1 cm per 5 units on the $$y$$-axis. [4]\n (e) Write down the coordinates of the point of intersection. [2]",
            answer:
              "(b)(i) $$f(x)=10x-2x^3+10-2x^2$$\n (b)(ii) $$f'(x)=10-6x^2-4x$$\n (e) $$(1.49,13.9)$$",
            solution:
              "(b)(i) Expand $$(2x+2)(5-x^2)=10x-2x^3+10-2x^2$$ (A1)\n (b)(ii) Differentiate term by term: $$f'(x)=10-6x^2-4x$$ (A1A1A1)\n (d) Plot cubic with correct intercepts, turning points, and endpoints, on the specified scale (A1A1A1A1)\n (e) Read/solve intersection of $$f$$ and $$g$$: $$(1.49,13.9)$$ (G1G1)",
