            calculator: true,
            question:
              "Let $$f(x)=12\\cos x-5\\sin x$$, $$-\\pi\\le x\\le2\\pi$$, periodic with $$f(x)=f(x+2\\pi)$$. There is a maximum point at A; the minimum value of $$f$$ is $$-13$$. A ball on a spring attached to fixed point $$O$$ moves back and forth vertically; the distance, $$d$$ cm, of the centre of the ball from $$O$$ at time $$t$$ seconds is $$d(t)=f(t)+17$$, $$0\\le t\\le5$$.\n (a) Find the coordinates of A. [2]\n (b)(i) For the graph of $$f$$, write down the amplitude. [1]\n (b)(ii) For the graph of $$f$$, write down the period. [1]\n (c) Hence, write $$f(t)$$ in the form $$p\\cos(t+r)$$. [3]\n (d) Find the maximum speed of the ball. [3]\n (e) Find the first time when the ball's speed is changing at a rate of $$2$$ cm s$$^{-2}$$. [5]",
            answer:
              '(a) $$(-0.395,13)$$\n (b)(i) amplitude $$=13$$\n (b)(ii) period $$=2\\pi$$\n (c) $$f(t)=13\\cos(t+0.395)$$\n (d) max speed $$=13$$ cm s$$^{-1}$$\n (e) $$t\\approx1.08$$ s',
            solution:
              "(a) A$$(-0.395,13)$$ (A1A1)\n (b) amplitude $$=13$$ (A1); period $$=2\\pi$$ (A1)\n (c) $$f(t)=13\\cos(t+0.395)$$ (M1A1A1)\n (d) $$d'(t)=-13\\sin(t+0.395)$$, max speed $$=13$$ (M1A1A1)\n (e) Solve $$|d''(t)|=2$$: $$t\\approx1.08$$ (M1A1M1A2)",
            questionType: 'Trigonometric modelling',
