            calculator: true,
            question:
              'A particle moves in a straight line. The velocity, $$v$$ m s$$^{-1}$$, at time $$t$$ seconds is $$v(t)=t\\sin t - 3$$, for $$0\\le t\\le10$$.\n (a) Find the smallest value of $$t$$ for which the particle is at rest. [2]\n (b) Find the total distance travelled by the particle. [2]\n (c) Find the acceleration of the particle when $$t=7$$. [2]',
            answer: '(a) $$t=6.74$$\n (b) $$\\approx37.1$$ m\n (c) $$\\approx5.93$$ m s$$^{-2}$$',
            solution:
              "(a) Solve $$v(t)=0$$ for smallest positive $$t$$: $$t=6.74$$ (M1A1)\n (b) $$\\int_0^{10}|v|\\,dt\\approx37.1$$ (A1A1)\n (c) $$v'(7)\\approx5.93$$ (M1A1)",
            questionType: 'Kinematics',
