            question:
              'The function $$f$$ is defined by $$f(x)=\\dfrac{4x+1}{x+4}$$, where $$x\\in\\mathbb{R},\\ x\\ne-4$$. The graphs of $$f$$ and $$f^{-1}$$ intersect at $$x=p$$ and $$x=q$$, where $$p<q$$.\n (a)(i) Write down the equation of the vertical asymptote. [1]\n (a)(ii) Find the equation of the horizontal asymptote. [2]\n (b)(i) Find $$f^{-1}(x)$$. [4]\n (b)(ii) Using an algebraic approach, show that the graph of $$f^{-1}$$ is obtained by a reflection of the graph of $$f$$ in the $$x$$-axis followed by a reflection in the $$y$$-axis. [4]\n (c)(i) Find the value of $$p$$ and the value of $$q$$. [2]\n (c)(ii) Hence, find the area enclosed by the graph of $$f$$ and the graph of $$f^{-1}$$. [3]',
            answer:
              '(a)(i) $$x=-4$$\n (a)(ii) $$y=4$$\n (b)(i) $$f^{-1}(x)=\\dfrac{1-4x}{x-4}$$\n (c)(i) $$p=-1,\\ q=1$$\n (c)(ii) $$0.675$$',
            solution:
              '(a)(i) $$x=-4$$ (A1)\n (a)(ii) $$y=4$$ (A1A1)\n (b)(i) Interchange $$x,y$$ in $$y=\\dfrac{4x+1}{x+4}$$ and solve for $$y$$: $$f^{-1}(x)=\\dfrac{1-4x}{x-4}$$ (M1A1A1A1)\n (b)(ii) Show $$-f(-x)=\\dfrac{1-4x}{x-4}=f^{-1}(x)$$ algebraically (M1A1M1AG)\n (c)(i) Solve $$f(x)=f^{-1}(x)$$: $$p=-1,\\ q=1$$ (M1A1)\n (c)(ii) $$\\int_{-1}^{1}\\left[f(x)-f^{-1}(x)\\right]dx\\approx0.675$$ (M1A1A1)',
            questionType: 'Rational functions / Inverse functions / Area',
            diagram: null,
            subtopicSlug: 'mixed-topics',
